function getProductSeed(productId) {
  const item = PRODUCTS.find((productItem) => productItem.id === productId);

  if (!item) {
    throw new Error(`Missing seeded product ${productId}`);
  }

  return item;
}

function stockIdForProduct(productId) {
  const item = getProductSeed(productId);

  if (!item.stockable || !item.stockId) {
    throw new Error(`Product ${productId} is not stockable or has no stockId`);
  }

  return item.stockId;
}

function orderLine(orderId, index, productId, quantiteCommandee, quantiteRecue) {
  const productItem = getProductSeed(productId);
  const prixUnitaireHT = Number(productItem.data.prixAchat || 0);
  const montantHT = quantiteCommandee * prixUnitaireHT;
  const montantTTC = Math.round(montantHT * 1.18);
  const padded = String(index).padStart(3, "0");

  return {
    id: `${orderId}-line-${padded}`,
    data: {
      commandeId: orderId,
      produitId: productId,
      stockId: stockIdForProduct(productId),
      designation: productItem.data.nom,
      quantiteCommandee,
      quantiteRecue,
      prixUnitaireHT,
      montantHT,
      montantTTC,
      statut: "validee",
      createdAt: NOW_ISO,
      updatedAt: NOW_ISO,
      seedTag: "TEST-DATA-PREP-A3",
    },
  };
}

function buildSupplyFlowDocuments() {
  const commandes = [];
  const lignes = [];
  const receptions = [];
  const mouvements = [];

  const receivedByProduct = new Map();

  for (const order of SUPPLY_ORDERS) {
    const montantHT = order.lines.reduce((sum, line) => sum + Number(line.data.montantHT || 0), 0);
    const montantTTC = order.lines.reduce((sum, line) => sum + Number(line.data.montantTTC || 0), 0);

    commandes.push({
      id: order.id,
      data: {
        ...order.data,
        montantHT,
        montantTTC,
      },
    });

    for (const line of order.lines) {
      lignes.push(line);

      if (Number(line.data.quantiteRecue || 0) <= 0) {
        continue;
      }

      const productItem = getProductSeed(line.data.produitId);
      const finalStock = Number(productItem.stock || 0);
      const alreadyReceived = Number(receivedByProduct.get(line.data.produitId) || 0);
      const quantite = Number(line.data.quantiteRecue || 0);
      const quantiteApres = finalStock - alreadyReceived;
      const quantiteAvant = quantiteApres - quantite;

      const receptionId = `demo-reception-${line.id.replace("demo-order-", "")}`;
      const mouvementId = `demo-movement-entry-${line.id.replace("demo-order-", "")}`;

      receptions.push({
        id: receptionId,
        data: {
          commandeId: line.data.commandeId,
          ligneCommandeId: line.id,
          produitId: line.data.produitId,
          stockId: line.data.stockId,
          quantiteRecue: quantite,
          dateReception: order.id.includes("old") ? daysFromNow(-108) : daysFromNow(-15),
          mouvementStockId: mouvementId,
          statut: "validee",
          notes: "Reception stock de demonstration generee par le seed AMARKHYS.",
          createdAt: NOW_ISO,
          updatedAt: NOW_ISO,
          seedTag: "TEST-DATA-PREP-A3",
        },
      });

      mouvements.push({
        id: mouvementId,
        data: {
          typeMouvement: "entree",
          stockId: line.data.stockId,
          produitId: line.data.produitId,
          quantite,
          quantiteAvant,
          quantiteApres,
          sourceModule: "receptionsstockauto",
          sourceId: receptionId,
          statut: "valide",
          dateMouvement: order.id.includes("old") ? daysFromNow(-108) : daysFromNow(-15),
          observations: "Mouvement entree stock genere depuis reception demo AMARKHYS.",
          createdAt: NOW_ISO,
          updatedAt: NOW_ISO,
          seedTag: "TEST-DATA-PREP-A3",
        },
      });

      receivedByProduct.set(line.data.produitId, alreadyReceived + quantite);
    }
  }

  return {
    commandes,
    lignes,
    receptions,
    mouvements,
  };
}
function loadEnvLocal() {
  const envPath = path.join(ROOT, ".env.local");

  if (!fs.existsSync(envPath)) {
    console.log("[ENV] .env.local not found, using current process.env only.");
    return;
  }

  const lines = fs.readFileSync(envPath, "utf8").split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith("#")) {
      continue;
    }

    const separatorIndex = trimmed.indexOf("=");

    if (separatorIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, separatorIndex).trim();
    let value = trimmed.slice(separatorIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (!process.env[key]) {
      process.env[key] = value;
    }
  }

  console.log("[ENV] .env.local loaded.");
}

function initFirebaseAdmin() {
  if (admin.apps.length > 0) {
    return admin.firestore();
  }

  const projectId =
    process.env.FIREBASE_PROJECT_ID ||
    process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID;

  if (!projectId) {
    throw new Error(
      "Missing Firebase project id. Expected FIREBASE_PROJECT_ID or NEXT_PUBLIC_FIREBASE_PROJECT_ID."
    );
  }

  if (projectId !== EXPECTED_PROJECT_ID) {
    throw new Error(
      `Unsafe project. Expected ${EXPECTED_PROJECT_ID}, received ${projectId}.`
    );
  }

  if (!process.env.GOOGLE_APPLICATION_CREDENTIALS) {
    throw new Error(
      "Missing GOOGLE_APPLICATION_CREDENTIALS. Set it to the local Firebase service account JSON."
    );
  }

  if (!fs.existsSync(process.env.GOOGLE_APPLICATION_CREDENTIALS)) {
    throw new Error(
      "GOOGLE_APPLICATION_CREDENTIALS file not found: " +
        process.env.GOOGLE_APPLICATION_CREDENTIALS
    );
  }

  console.log("[FIREBASE] Project:", projectId);
  console.log("[FIREBASE] Credentials:", process.env.GOOGLE_APPLICATION_CREDENTIALS);

  admin.initializeApp({
    projectId,
    credential: admin.credential.applicationDefault(),
  });

  return admin.firestore();
}

async function countCollection(db, collectionName) {
  const snapshot = await db.collection(collectionName).count().get();
  return snapshot.data().count || 0;
}

async function assertSafeTargetCollections() {
  const protectedOverlap = TARGET_COLLECTIONS.filter((collectionName) =>
    PROTECTED_COLLECTIONS.includes(collectionName)
  );

  if (protectedOverlap.length > 0) {
    throw new Error(
      "Unsafe configuration. Target collections include protected collections: " +
        protectedOverlap.join(", ")
    );
  }
}

