async function seedSupplyFlow(db) {
  const docs = buildSupplyFlowDocuments();

  console.log("");
  console.log("[PLAN] Supply flow seed");
  console.log(`- commandesstockauto: ${docs.commandes.length}`);
  console.log(`- lignescommandestockauto: ${docs.lignes.length}`);
  console.log(`- receptionsstockauto: ${docs.receptions.length}`);
  console.log(`- mouvementsstockauto: ${docs.mouvements.length}`);
  console.log("");

  if (!seedSupplyFlowEnabled) {
    console.log("[DRY-RUN] No supply flow document will be written.");
    console.log("To write supply flow data, run with --confirm-seed-supply-flow");
    return;
  }

  console.log("[WRITE START]");

  for (const order of docs.commandes) {
    await writeDoc(db, "commandesstockauto", order.id, order.data);
    console.log(`[WRITE] commandesstockauto/${order.id}`);
  }

  for (const line of docs.lignes) {
    await writeDoc(db, "lignescommandestockauto", line.id, line.data);
    console.log(`[WRITE] lignescommandestockauto/${line.id}`);
  }

  for (const reception of docs.receptions) {
    await writeDoc(db, "receptionsstockauto", reception.id, reception.data);
    console.log(`[WRITE] receptionsstockauto/${reception.id}`);
  }

  for (const movement of docs.mouvements) {
    await writeDoc(db, "mouvementsstockauto", movement.id, movement.data);
    console.log(`[WRITE] mouvementsstockauto/${movement.id}`);
  }

  console.log("[WRITE DONE]");
}
